insert into vocabulary (id, word, ipa, part_of_speech, translation_pt, example_en, example_pt, cefr_level, tags) values
('30000000-0000-0000-0000-000000002071', 'if I had known', '/ɪf aɪ hæd noʊn/', 'phrase', 'se eu tivesse sabido', 'If I had known about the meeting, I would have come.', 'Se eu tivesse sabido da reunião, eu teria vindo.', 'B2', array['review']),
('30000000-0000-0000-0000-000000002072', 'must have been', '/mʌst hæv bɪn/', 'phrase', 'deve ter sido', 'It must have been difficult to finish the project so fast.', 'Deve ter sido difícil terminar o projeto tão rápido.', 'B2', array['review']),
('30000000-0000-0000-0000-000000002073', 'whose', '/huːz/', 'pronoun', 'cujo', 'That is the engineer whose design won the award.', 'Aquele é o engenheiro cujo projeto ganhou o prêmio.', 'B2', array['review']),
('30000000-0000-0000-0000-000000002074', 'not only...but also', '/nɑːt ˈoʊnli bʌt ˈɔːlsoʊ/', 'phrase', 'não apenas...mas também', 'Not only did they finish early, but they also saved money.', 'Eles não apenas terminaram cedo, mas também economizaram dinheiro.', 'B2', array['review']),
('30000000-0000-0000-0000-000000002075', 'as long as', '/æz lɔːŋ æz/', 'conjunction', 'contanto que', 'You can join the call, as long as you are on time.', 'Você pode entrar na ligação, contanto que esteja no horário.', 'B2', array['review']),
('30000000-0000-0000-0000-000000002076', 'even though', '/ˈiːvən ðoʊ/', 'conjunction', 'mesmo que', 'Even though it was late, the team kept working.', 'Mesmo estando tarde, a equipe continuou trabalhando.', 'B2', array['review']),
('30000000-0000-0000-0000-000000002077', 'give up', '/ɡɪv ʌp/', 'verb', 'desistir', 'Never give up on a project just because it gets difficult.', 'Nunca desista de um projeto só porque ele fica difícil.', 'B2', array['review']),
('30000000-0000-0000-0000-000000002078', 'deadline', '/ˈdedlaɪn/', 'noun', 'prazo final', 'We need to meet the deadline on Friday.', 'Precisamos cumprir o prazo final na sexta-feira.', 'B2', array['review']),
('30000000-0000-0000-0000-000000002079', 'career growth', '/kəˈrɪər ɡroʊθ/', 'noun', 'crescimento de carreira', 'She joined the company for the career growth opportunities.', 'Ela entrou na empresa pelas oportunidades de crescimento de carreira.', 'B2', array['review']),
('30000000-0000-0000-0000-000000002080', 'leverage', '/ˈlevərɪdʒ/', 'noun', 'poder de barganha', 'Strong sales numbers gave the team more leverage in the negotiation.', 'Números de vendas fortes deram à equipe mais poder de barganha na negociação.', 'B2', array['review']),
('30000000-0000-0000-0000-000000002081', 'reach an agreement', '/riːtʃ ən əˈɡriːmənt/', 'phrase', 'chegar a um acordo', 'After hours of talks, they finally reached an agreement.', 'Depois de horas de conversa, eles finalmente chegaram a um acordo.', 'B2', array['review']),
('30000000-0000-0000-0000-000000002082', 'compelling', '/kəmˈpelɪŋ/', 'adjective', 'convincente', 'She made a compelling case for the new strategy.', 'Ela apresentou um argumento convincente para a nova estratégia.', 'B2', array['review']),
('30000000-0000-0000-0000-000000002083', 'it was...who', '/ɪt wɒz huː/', 'phrase', 'foi...quem', 'It was the marketing team who came up with the idea.', 'Foi a equipe de marketing quem teve a ideia.', 'B2', array['review']),
('30000000-0000-0000-0000-000000002084', 'is being reviewed', '/ɪz ˈbiːɪŋ rɪˈvjuːd/', 'phrase', 'está sendo revisado', 'The contract is being reviewed by our legal team.', 'O contrato está sendo revisado pela nossa equipe jurídica.', 'B2', array['review']),
('30000000-0000-0000-0000-000000002085', 'he asked if', '/hiː æskt ɪf/', 'phrase', 'ele perguntou se', 'He asked if the meeting had been rescheduled.', 'Ele perguntou se a reunião tinha sido reagendada.', 'B2', array['review']),
('30000000-0000-0000-0000-000000002086', 'however', '/haʊˈevər/', 'adverb', 'no entanto', 'The plan was ambitious. However, the team pulled it off.', 'O plano era ambicioso. No entanto, a equipe conseguiu.', 'B2', array['review']),
('30000000-0000-0000-0000-000000002087', 'in conclusion', '/ɪn kənˈkluːʒən/', 'phrase', 'em conclusão', 'In conclusion, our strategy needs to change.', 'Em conclusão, nossa estratégia precisa mudar.', 'B2', array['review']),
('30000000-0000-0000-0000-000000002088', 'previously', '/ˈpriːviəsli/', 'adverb', 'anteriormente', 'The role was previously held by someone else.', 'O cargo era anteriormente ocupado por outra pessoa.', 'B2', array['review']),
('30000000-0000-0000-0000-000000002089', 'responsible for', '/rɪˈspɑːnsəbəl fɔːr/', 'phrase', 'responsável por', 'She is responsible for the entire marketing budget.', 'Ela é responsável por todo o orçamento de marketing.', 'B2', array['review']),
('30000000-0000-0000-0000-000000002090', 'access to', '/ˈækses tuː/', 'phrase', 'acesso a', 'All employees now have access to the new system.', 'Todos os funcionários agora têm acesso ao novo sistema.', 'B2', array['review']),
('30000000-0000-0000-0000-000000002091', 'I am writing to', '/aɪ æm ˈraɪtɪŋ tuː/', 'phrase', 'estou escrevendo para', 'I am writing to confirm our meeting tomorrow.', 'Estou escrevendo para confirmar nossa reunião amanhã.', 'B2', array['review']),
('30000000-0000-0000-0000-000000002092', 'proofread', '/ˈpruːfriːd/', 'verb', 'revisar', 'Always proofread important emails before sending them.', 'Sempre revise e-mails importantes antes de enviá-los.', 'B2', array['review']),
('30000000-0000-0000-0000-000000002093', 'demonstrate', '/ˈdemənstreɪt/', 'verb', 'demonstrar', 'The results demonstrate real progress this quarter.', 'Os resultados demonstram um progresso real neste trimestre.', 'B2', array['review']),
('30000000-0000-0000-0000-000000002094', 'significant', '/sɪɡˈnɪfɪkənt/', 'adjective', 'significativo', 'There was a significant improvement in customer satisfaction.', 'Houve uma melhora significativa na satisfação do cliente.', 'B2', array['review']),
('30000000-0000-0000-0000-000000002095', 'break the ice', '/breɪk ðə aɪs/', 'phrase', 'quebrar o gelo', 'A simple question can break the ice in any meeting.', 'Uma pergunta simples pode quebrar o gelo em qualquer reunião.', 'B2', array['review']),
('30000000-0000-0000-0000-000000002096', 'cost an arm and a leg', '/kɔːst ən ɑːrm ænd ə leɡ/', 'phrase', 'custar muito caro', 'That software update cost an arm and a leg.', 'Aquela atualização de software custou os olhos da cara.', 'B2', array['review']),
('30000000-0000-0000-0000-000000002097', 'sustainability', '/səˌsteɪnəˈbɪləti/', 'noun', 'sustentabilidade', 'Sustainability is now part of every business decision.', 'Sustentabilidade agora faz parte de toda decisão de negócio.', 'B2', array['review']),
('30000000-0000-0000-0000-000000002098', 'carbon footprint', '/ˈkɑːrbən ˈfʊtprɪnt/', 'noun', 'pegada de carbono', 'The company measured its carbon footprint for the first time.', 'A empresa mediu sua pegada de carbono pela primeira vez.', 'B2', array['review']),
('30000000-0000-0000-0000-000000002099', 'by the time', '/baɪ ðə taɪm/', 'conjunction', 'quando', 'By the time the presentation ended, everyone had many questions.', 'Quando a apresentação terminou, todos tinham muitas perguntas.', 'B2', array['review']),
('30000000-0000-0000-0000-000000002100', 'take action', '/teɪk ˈækʃən/', 'phrase', 'agir', 'It is time for every department to take action.', 'É hora de cada departamento agir.', 'B2', array['review']);

