-- Lição 346: Condicionais e modais (if I had known, must have been, whose, not only...but also, as long as, even though)
insert into exercises (lesson_id, type, sort_order, content) values
('20000000-0000-0000-0000-000000000346', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000002071", "show_image": false}'),
('20000000-0000-0000-0000-000000000346', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000002072", "show_image": false}'),
('20000000-0000-0000-0000-000000000346', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000002073", "show_image": false}'),
('20000000-0000-0000-0000-000000000346', 'multiple_choice', 4, '{"question": "___ about the meeting, I would have come.", "audio_text": null, "options": ["If I had known", "As long as I know", "Even though I know"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000346', 'multiple_choice', 5, '{"question": "That is the engineer ___ design won the award.", "audio_text": null, "options": ["whose", "who", "which"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000346', 'matching', 6, '{"pairs": [{"left": "if I had known", "right": "se eu tivesse sabido"}, {"left": "must have been", "right": "deve ter sido"}, {"left": "whose", "right": "cujo"}, {"left": "not only...but also", "right": "não apenas...mas também"}, {"left": "as long as", "right": "contanto que"}, {"left": "even though", "right": "mesmo que"}]}'),
('20000000-0000-0000-0000-000000000346', 'fill_blank', 7, '{"sentence": "It ___ difficult to finish the project so fast.", "options": ["must have been", "must be", "had been"], "correct": "must have been", "translation": "Deve ter sido difícil terminar o projeto tão rápido."}'),
('20000000-0000-0000-0000-000000000346', 'fill_blank', 8, '{"sentence": "You can join the call, ___ you are on time.", "options": ["as long as", "even though", "whose"], "correct": "as long as", "translation": "Você pode entrar na ligação, contanto que esteja no horário."}'),
('20000000-0000-0000-0000-000000000346', 'word_order', 9, '{"words": ["Not", "only", "did", "they", "finish", "early", "but", "they", "also", "saved", "money"], "correct_sentence": "Not only did they finish early but they also saved money", "translation": "Eles não apenas terminaram cedo, mas também economizaram dinheiro"}'),
('20000000-0000-0000-0000-000000000346', 'word_order', 10, '{"words": ["Even", "though", "it", "was", "late", "the", "team", "kept", "working"], "correct_sentence": "Even though it was late the team kept working", "translation": "Mesmo estando tarde, a equipe continuou trabalhando"}'),
('20000000-0000-0000-0000-000000000346', 'reading', 11, '{"passage": "The B2 level introduced several advanced structures. Third conditionals like ''if I had known'' describe hypothetical pasts, while modals of deduction like ''must have been'' express confident guesses about the past. Relative clauses with ''whose'' add extra detail, and inversion with ''not only...but also'' adds emphasis to a sentence.", "translation": "O nível B2 introduziu várias estruturas avançadas. Condicionais do terceiro tipo como ''if I had known'' descrevem passados hipotéticos, enquanto modais de dedução como ''must have been'' expressam suposições confiantes sobre o passado. Orações relativas com ''whose'' acrescentam detalhes extras, e a inversão com ''not only...but also'' acrescenta ênfase a uma frase.", "question": "What do modals like ''must have been'' express, according to the text?", "options": ["A hypothetical future", "A confident guess about the past", "A polite request"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000346', 'listening', 12, '{"audio_text": "If I had known about the meeting, I would have come. That is the engineer whose design won the award. Even though it was late, the team kept working.", "question": "Whose design won the award, according to the audio?", "options": ["The manager''s", "The engineer''s", "The client''s"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000346', 'dictation', 13, '{"audio_text": "If I had known about the meeting, I would have come.", "expected": "If I had known about the meeting, I would have come."}'),
('20000000-0000-0000-0000-000000000346', 'typing', 14, '{"prompt_pt": "Traduza: ''Se eu tivesse sabido, teria mudado o prazo, contanto que a equipe concordasse.''", "expected": "If I had known, I would have changed the deadline, as long as the team agreed.", "ai_review": true}'),

-- Lição 347: Vocabulário de negócios (give up, deadline, career growth, leverage, reach an agreement, compelling)
('20000000-0000-0000-0000-000000000347', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000002077", "show_image": false}'),
('20000000-0000-0000-0000-000000000347', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000002078", "show_image": false}'),
('20000000-0000-0000-0000-000000000347', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000002081", "show_image": false}'),
('20000000-0000-0000-0000-000000000347', 'multiple_choice', 4, '{"question": "We need to meet the ___ on Friday.", "audio_text": null, "options": ["deadline", "leverage", "agreement"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000347', 'multiple_choice', 5, '{"question": "She made a ___ case for the new strategy.", "audio_text": null, "options": ["compelling", "previous", "significant"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000347', 'matching', 6, '{"pairs": [{"left": "give up", "right": "desistir"}, {"left": "deadline", "right": "prazo final"}, {"left": "career growth", "right": "crescimento de carreira"}, {"left": "leverage", "right": "poder de barganha"}, {"left": "reach an agreement", "right": "chegar a um acordo"}, {"left": "compelling", "right": "convincente"}]}'),
('20000000-0000-0000-0000-000000000347', 'fill_blank', 7, '{"sentence": "She joined the company for the ___ opportunities.", "options": ["career growth", "deadline", "leverage"], "correct": "career growth", "translation": "Ela entrou na empresa pelas oportunidades de crescimento de carreira."}'),
('20000000-0000-0000-0000-000000000347', 'fill_blank', 8, '{"sentence": "After hours of talks, they finally ___.", "options": ["reached an agreement", "gave up", "demonstrated"], "correct": "reached an agreement", "translation": "Depois de horas de conversa, eles finalmente chegaram a um acordo."}'),
('20000000-0000-0000-0000-000000000347', 'word_order', 9, '{"words": ["Never", "give", "up", "on", "a", "project", "just", "because", "it", "gets", "difficult"], "correct_sentence": "Never give up on a project just because it gets difficult", "translation": "Nunca desista de um projeto só porque ele fica difícil"}'),
('20000000-0000-0000-0000-000000000347', 'word_order', 10, '{"words": ["Strong", "sales", "numbers", "gave", "the", "team", "more", "leverage", "in", "the", "negotiation"], "correct_sentence": "Strong sales numbers gave the team more leverage in the negotiation", "translation": "Números de vendas fortes deram à equipe mais poder de barganha na negociação"}'),
('20000000-0000-0000-0000-000000000347', 'reading', 11, '{"passage": "Business vocabulary connects many B2 modules. A team under pressure to meet a deadline should never give up, and strong results often mean more career growth and leverage in future negotiations. In the end, a compelling case usually helps both sides reach an agreement faster.", "translation": "Vocabulário de negócios conecta muitos módulos do B2. Uma equipe sob pressão para cumprir um deadline nunca deve give up, e bons resultados costumam significar mais career growth e leverage em negociações futuras. No final, um caso compelling costuma ajudar os dois lados a reach an agreement mais rápido.", "question": "What often helps both sides reach an agreement faster, according to the text?", "options": ["Giving up", "A compelling case", "Missing the deadline"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000347', 'listening', 12, '{"audio_text": "We need to meet the deadline on Friday. She joined the company for the career growth opportunities. After hours of talks, they finally reached an agreement.", "question": "When is the deadline, according to the audio?", "options": ["Monday", "Friday", "Next month"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000347', 'dictation', 13, '{"audio_text": "We need to meet the deadline on Friday.", "expected": "We need to meet the deadline on Friday."}'),
('20000000-0000-0000-0000-000000000347', 'typing', 14, '{"prompt_pt": "Traduza: ''Nunca desista antes do prazo final; um argumento convincente pode ajudar a chegar a um acordo.''", "expected": "Never give up before the deadline; a compelling argument can help reach an agreement.", "ai_review": true}'),

-- Lição 348: Passiva e discurso indireto (it was...who, is being reviewed, he asked if, however, in conclusion, previously)
('20000000-0000-0000-0000-000000000348', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000002083", "show_image": false}'),
('20000000-0000-0000-0000-000000000348', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000002084", "show_image": false}'),
('20000000-0000-0000-0000-000000000348', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000002085", "show_image": false}'),
('20000000-0000-0000-0000-000000000348', 'multiple_choice', 4, '{"question": "The contract ___ by our legal team.", "audio_text": null, "options": ["is being reviewed", "reviews", "was review"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000348', 'multiple_choice', 5, '{"question": "He asked ___ the meeting had been rescheduled.", "audio_text": null, "options": ["if", "that", "who"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000348', 'matching', 6, '{"pairs": [{"left": "it was...who", "right": "foi...quem"}, {"left": "is being reviewed", "right": "está sendo revisado"}, {"left": "he asked if", "right": "ele perguntou se"}, {"left": "however", "right": "no entanto"}, {"left": "in conclusion", "right": "em conclusão"}, {"left": "previously", "right": "anteriormente"}]}'),
('20000000-0000-0000-0000-000000000348', 'fill_blank', 7, '{"sentence": "The plan was ambitious. ___, the team pulled it off.", "options": ["However", "In conclusion", "Previously"], "correct": "However", "translation": "O plano era ambicioso. No entanto, a equipe conseguiu."}'),
('20000000-0000-0000-0000-000000000348', 'fill_blank', 8, '{"sentence": "The role was ___ held by someone else.", "options": ["previously", "however", "in conclusion"], "correct": "previously", "translation": "O cargo era anteriormente ocupado por outra pessoa."}'),
('20000000-0000-0000-0000-000000000348', 'word_order', 9, '{"words": ["It", "was", "the", "marketing", "team", "who", "came", "up", "with", "the", "idea"], "correct_sentence": "It was the marketing team who came up with the idea", "translation": "Foi a equipe de marketing quem teve a ideia"}'),
('20000000-0000-0000-0000-000000000348', 'word_order', 10, '{"words": ["In", "conclusion", "our", "strategy", "needs", "to", "change"], "correct_sentence": "In conclusion our strategy needs to change", "translation": "Em conclusão, nossa estratégia precisa mudar"}'),
('20000000-0000-0000-0000-000000000348', 'reading', 11, '{"passage": "Passive voice, cleft sentences, and reported speech all help writers control focus and tone. ''It was the marketing team who came up with the idea'' emphasizes who acted, while ''the contract is being reviewed'' focuses on the action itself. ''He asked if the meeting had been rescheduled'' reports a question, and connectors like ''however'', ''in conclusion'' and ''previously'' organize the whole text.", "translation": "Voz passiva, cleft sentences e discurso indireto ajudam escritores a controlar foco e tom. ''It was the marketing team who came up with the idea'' enfatiza quem agiu, enquanto ''the contract is being reviewed'' foca na ação em si. ''He asked if the meeting had been rescheduled'' relata uma pergunta, e conectores como ''however'', ''in conclusion'' e ''previously'' organizam todo o texto.", "question": "What does the passive ''the contract is being reviewed'' focus on, according to the text?", "options": ["Who is reviewing it", "The action itself", "When it happened"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000348', 'listening', 12, '{"audio_text": "The contract is being reviewed by our legal team. He asked if the meeting had been rescheduled. In conclusion, our strategy needs to change.", "question": "Who is reviewing the contract, according to the audio?", "options": ["The sales team", "Our legal team", "The marketing team"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000348', 'dictation', 13, '{"audio_text": "The contract is being reviewed by our legal team.", "expected": "The contract is being reviewed by our legal team."}'),
('20000000-0000-0000-0000-000000000348', 'typing', 14, '{"prompt_pt": "Traduza: ''Ele perguntou se o contrato ainda estava sendo revisado; no entanto, ainda não havia resposta.''", "expected": "He asked if the contract was still being reviewed; however, there was still no answer.", "ai_review": true}'),

